using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Text.Json;
using E=Rizan.Portfolio.Eur;
var rows=new List<E.Candle>();foreach(var line in File.ReadLines(args[0]).Skip(1)){var p=line.Split(',');rows.Add(new(DateTime.Parse(p[0],CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal|DateTimeStyles.AdjustToUniversal),double.Parse(p[1],CultureInfo.InvariantCulture),double.Parse(p[2],CultureInfo.InvariantCulture),double.Parse(p[3],CultureInfo.InvariantCulture),double.Parse(p[4],CultureInfo.InvariantCulture)));}
var native=new E.EurState();var features=E.FrozenCore.EurFeatures(rows,rows[^1].End(1),native);var signals=features.Select(E.FrozenCore.EurSignal).OfType<E.Signal>().ToDictionary(s=>s.AtUtc);var state=new E.EurState();E.Candle? previous=null;var result=new List<object>();
foreach(var b in rows){if(previous!=null&&state.Virtual!=null){var exit=E.FrozenCore.VirtualStep(state.Virtual,previous);if(exit!=null){state.Fast=2d/3*exit.Value.R+state.Fast/3;state.Slow=2d/9*exit.Value.R+7d/9*state.Slow;state.LastExitUtc=exit.Value.AtUtc;state.Virtual=null;}}
 if(signals.TryGetValue(b.OpenUtc,out var s)){result.Add(new{At=s.AtUtc,Side=s.Side,Distance=s.Distance,AsiaExtra=s.AsiaExtra,Fast=state.Fast,Slow=state.Slow,Scale=Math.Min(E.FrozenCore.EurScale(state),s.AsiaExtra?.1:1)});if(state.Virtual==null&&(state.LastExitUtc==default||b.OpenUtc>state.LastExitUtc))state.Virtual=new(){AtUtc=s.AtUtc,LastUtc=s.AtUtc,LastClose=b.Open,Side=s.Side,Distance=s.Distance,Entry=b.Open+(s.Side==1?.00012:0)+s.Side*.00001};}previous=b;}
if(previous!=null&&state.Virtual!=null){var exit=E.FrozenCore.VirtualStep(state.Virtual,previous);if(exit!=null){state.Fast=2d/3*exit.Value.R+state.Fast/3;state.Slow=2d/9*exit.Value.R+7d/9*state.Slow;state.Virtual=null;}}
E.FrozenCore.AdvanceVirtual(rows,features,native);if(Math.Abs(native.Fast-state.Fast)>1e-10||Math.Abs(native.Slow-state.Slow)>1e-10)throw new Exception("NATIVE_ADVANCE_VIRTUAL_PARITY_FAILED");
File.WriteAllText(args[1],JsonSerializer.Serialize(result));Console.WriteLine(JsonSerializer.Serialize(new{Signals=result.Count,AsiaExtra=signals.Values.Count(s=>s.AsiaExtra),NativeAdvanceVirtualParity=true}));
